#include <iostream>
#include <vector>
#include <string>
#include <unordered_set>
using namespace std;

int main() {
    long long n;
    cin >> n;

    unordered_set<long long> seen;
    while (n != 1 && !seen.count(n)) {
        seen.insert(n);
        long long total = 0;
        while (n > 0) {
            total += (n % 10) * (n % 10);
            n /= 10;
        }
        n = total;
    }
    cout << (n == 1 ? "yes" : "no") << "\n";

    return 0;
}

code.java:
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();

        Set<Long> seen = new HashSet<>();
        while (n != 1 && !seen.contains(n)) {
            seen.add(n);
            long total = 0;
            while (n > 0) {
                total += (n % 10) * (n % 10);
                n /= 10;
            }
            n = total;
        }
        System.out.println(n == 1 ? "yes" : "no");
    }
}
